import torch

@torch.inference_mode()
def next_token(model, prefix, generator=None):
    """Sample one token; model and prefix are explicit dependencies."""
    model.eval()
    logits = model(prefix)[:, -1, :]
    probabilities = logits.softmax(dim=-1)
    return torch.multinomial(probabilities, 1, generator=generator)
